<script setup lang="ts">
import { crmDestination } from '~/shared/crm-workspace';
import { AlertTriangle, ArrowDownRight, ArrowUpRight, Boxes, CircleDollarSign, ClipboardList, RefreshCw, Users } from '@lucide/vue';
const config = useRuntimeConfig();
const route = useRoute();
const { token } = useWorkspaceSession();
const data = ref<any>(null);
const loading = ref(false);
const error = ref('');
const props = defineProps<{ pageSection?: string }>();
const section = computed(() => props.pageSection || String(route.query.section || 'overview'));
const titles: Record<string,{eyebrow:string;title:string;description:string}> = {
  overview: { eyebrow:'КОМПАНИЯ / 30 ДНЕЙ', title:'Пульс бизнеса', description:'Результаты и точки внимания в пределах ваших прав доступа' },
  sales: { eyebrow:'ФИНАНСОВЫЙ СРЕЗ', title:'Продажи и каналы', description:'Оборот, количество заказов и вклад каждого канала' },
  customers: { eyebrow:'КЛИЕНТСКАЯ АНАЛИТИКА', title:'Клиенты и развитие', description:'Рост клиентской базы, CRM-нагрузка и качество сервиса' },
};
const title = computed(() => { const page = titles[section.value] || titles.overview; return { ...page, title: crmDestination(route.path)?.label || page.title }; });
const money = (value: number | null) => value == null ? '—' : Number(value).toLocaleString('ru-RU', { maximumFractionDigits: 0 }) + ' ₽';
const channelLabels: Record<string,string> = { WEB:'Интернет-магазин',B2B:'B2B',WILDBERRIES:'Wildberries',OZON:'Ozon',YANDEX_MARKET:'Яндекс Маркет',MEGAMARKET:'Мегамаркет',MANUAL:'Ручной заказ',ONE_C:'1С' };
const salesChannels = computed(() => data.value?.channels || []);
const maxChannelRevenue = computed(() => Math.max(1, ...salesChannels.value.map((item:any) => Number(item.revenue || 0))));
let requestVersion = 0;
let controller: AbortController | undefined;
async function load() {
  const version = ++requestVersion, identity = token.value;
  controller?.abort(); controller = new AbortController();
  loading.value = true; error.value = ''; data.value = null;
  try {
    const result = await $fetch('/leadership/overview', { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${identity}` }, signal: controller.signal });
    if (version === requestVersion && token.value === identity) data.value = result;
  } catch (e: any) {
    if (version === requestVersion && token.value === identity) error.value = e?.data?.message || 'Не удалось загрузить управленческие показатели';
  } finally { if (version === requestVersion) loading.value = false; }
}
watch(token, () => { ++requestVersion; controller?.abort(); data.value = null; if (token.value) void load(); });
onMounted(load);
onUnmounted(() => { ++requestVersion; controller?.abort(); });
</script>

<template><main data-v-ui-f25044a38e22 class="leader-page crm-standard"><header data-v-ui-f25044a38e22 class="leader-header crm-page-header"><div data-v-ui-f25044a38e22><p data-v-ui-f25044a38e22 class="eyebrow">{{ title.eyebrow }}</p><h1 data-v-ui-f25044a38e22>{{ title.title }}</h1><span data-v-ui-f25044a38e22>{{ title.description }}</span></div><button class="crm-button crm-button--refresh" data-v-ui-f25044a38e22 @click="load"><RefreshCw data-v-ui-f25044a38e22 :size="16" :class="{spin:loading}" /> Обновить данные</button></header><WorkspaceLoading v-if="!data && loading" label="Собираем показатели компании" /><div data-v-ui-f25044a38e22 v-else-if="error" class="load-error"><AlertTriangle data-v-ui-f25044a38e22 :size="22" /><span data-v-ui-f25044a38e22>{{ error }}</span><button class="crm-button" data-v-ui-f25044a38e22 @click="load">Повторить</button></div><div data-v-ui-f25044a38e22 v-else-if="data" class="leader-body crm-page-content"><p v-if="data.access && Object.values(data.access).some(value => !value)" class="crm-muted" role="status">Часть разделов недоступна. Прочерк означает отсутствие доступа, а не нулевой результат.</p>
  <p class="crm-notice">Здесь показана операционная статистика заказов с онлайн-оплатой по дате создания заказа. Финансовый учёт, взаиморасчёты и отчётность ведутся в 1С.</p><template v-if="section === 'overview'"><section data-v-ui-f25044a38e22 class="hero-kpis"><article data-v-ui-f25044a38e22 class="revenue crm-surface--tint crm-surface"><span data-v-ui-f25044a38e22>Онлайн-оплаченные заказы за 30 дней</span><strong data-v-ui-f25044a38e22>{{ money(data.sales.revenue) }}</strong><small data-v-ui-f25044a38e22 :class="data.sales.growth == null ? '' : data.sales.growth >= 0 ? 'positive' : 'negative'"><ArrowUpRight data-v-ui-f25044a38e22 v-if="data.sales.growth !== null && data.sales.growth >= 0" :size="14" /><ArrowDownRight data-v-ui-f25044a38e22 v-else-if="data.sales.growth !== null" :size="14" />{{ data.sales.growth === null ? 'Недостаточно данных для сравнения' : Math.abs(data.sales.growth).toFixed(1) + '% к прошлому периоду' }}</small></article><article class="crm-surface" data-v-ui-f25044a38e22><ClipboardList data-v-ui-f25044a38e22 :size="19" /><span data-v-ui-f25044a38e22>Оплаченные заказы</span><strong data-v-ui-f25044a38e22>{{ data.sales.orders ?? '—' }}</strong><small data-v-ui-f25044a38e22>Средний чек {{ money(data.sales.averageOrder) }}</small></article><article class="crm-surface" data-v-ui-f25044a38e22><Users data-v-ui-f25044a38e22 :size="19" /><span data-v-ui-f25044a38e22>Клиенты</span><strong data-v-ui-f25044a38e22>{{ data.customers.total ?? '—' }}</strong><small data-v-ui-f25044a38e22>{{ data.customers.new == null ? '—' : '+' + data.customers.new }} за 30 дней</small></article><article class="crm-surface" data-v-ui-f25044a38e22><Boxes data-v-ui-f25044a38e22 :size="19" /><span data-v-ui-f25044a38e22>Товарные риски</span><strong data-v-ui-f25044a38e22>{{ data.operations.lowStock ?? '—' }}</strong><small data-v-ui-f25044a38e22>позиций с малым остатком</small></article></section><section data-v-ui-f25044a38e22 class="overview-grid"><article data-v-ui-f25044a38e22 class="panel crm-surface"><div data-v-ui-f25044a38e22 class="panel-head"><div data-v-ui-f25044a38e22><p data-v-ui-f25044a38e22 class="eyebrow">КАНАЛЫ ПРОДАЖ</p><h2 data-v-ui-f25044a38e22>Суммы заказов по каналам</h2></div><NuxtLink data-v-ui-f25044a38e22 :to="route.path.startsWith('/crm/') ? '/crm/reports/sales' : '/leadership?section=sales'">Подробнее</NuxtLink></div><div data-v-ui-f25044a38e22 v-for="item in salesChannels" :key="item.channel" class="channel-row"><div data-v-ui-f25044a38e22><strong data-v-ui-f25044a38e22>{{ channelLabels[item.channel] || item.channel }}</strong><small data-v-ui-f25044a38e22>{{ item.orders }} заказов</small></div><span data-v-ui-f25044a38e22>{{ money(item.revenue) }}</span><i data-v-ui-f25044a38e22><b data-v-ui-f25044a38e22 :style="{width:`${Math.max(4, Number(item.revenue || 0) / maxChannelRevenue * 100)}%`}"></b></i></div><p data-v-ui-f25044a38e22 v-if="!salesChannels.length" class="empty">{{ data.access?.sales === false ? 'Нет доступа к данным продаж' : 'В доступной области пока нет подтверждённых оплат' }}</p></article><article data-v-ui-f25044a38e22 class="panel attention crm-surface"><div data-v-ui-f25044a38e22 class="panel-head"><div data-v-ui-f25044a38e22><p data-v-ui-f25044a38e22 class="eyebrow">ТРЕБУЕТ ВНИМАНИЯ</p><h2 data-v-ui-f25044a38e22>Операционные риски</h2></div></div><div data-v-ui-f25044a38e22 class="risk"><i data-v-ui-f25044a38e22 class="danger crm-icon-tile--danger"><AlertTriangle data-v-ui-f25044a38e22 :size="17" /></i><span data-v-ui-f25044a38e22><strong data-v-ui-f25044a38e22>Просроченные обращения</strong><small data-v-ui-f25044a38e22>Нарушен срок решения Helpdesk</small></span><b data-v-ui-f25044a38e22>{{ data.operations.helpdeskOverdue ?? '—' }}</b></div><div data-v-ui-f25044a38e22 class="risk"><i data-v-ui-f25044a38e22><HeadphonesIcon /></i><span data-v-ui-f25044a38e22><strong data-v-ui-f25044a38e22>Открытые обращения</strong><small data-v-ui-f25044a38e22>В работе у IT-команды</small></span><b data-v-ui-f25044a38e22>{{ data.operations.helpdeskOpen ?? '—' }}</b></div><div data-v-ui-f25044a38e22 class="risk"><i data-v-ui-f25044a38e22><ClipboardList data-v-ui-f25044a38e22 :size="17" /></i><span data-v-ui-f25044a38e22><strong data-v-ui-f25044a38e22>Активные задачи</strong><small data-v-ui-f25044a38e22>Задачи в доступной области</small></span><b data-v-ui-f25044a38e22>{{ data.operations.activeTasks ?? '—' }}</b></div><div data-v-ui-f25044a38e22 class="risk"><i data-v-ui-f25044a38e22><Users data-v-ui-f25044a38e22 :size="17" /></i><span data-v-ui-f25044a38e22><strong data-v-ui-f25044a38e22>Открытые лиды</strong><small data-v-ui-f25044a38e22>Требуют движения по воронке</small></span><b data-v-ui-f25044a38e22>{{ data.operations.openLeads ?? '—' }}</b></div></article></section></template>
  <template v-else-if="section === 'sales'"><section data-v-ui-f25044a38e22 class="hero-kpis"><article data-v-ui-f25044a38e22 class="revenue crm-surface--tint crm-surface"><span data-v-ui-f25044a38e22>Сумма онлайн-оплаченных заказов</span><strong data-v-ui-f25044a38e22>{{ money(data.sales.revenue) }}</strong><small data-v-ui-f25044a38e22>За последние 30 дней</small></article><article class="crm-surface" data-v-ui-f25044a38e22><CircleDollarSign data-v-ui-f25044a38e22 :size="19" /><span data-v-ui-f25044a38e22>Прошлый период</span><strong data-v-ui-f25044a38e22>{{ money(data.sales.previousRevenue) }}</strong><small data-v-ui-f25044a38e22>База для сравнения</small></article><article class="crm-surface" data-v-ui-f25044a38e22><ClipboardList data-v-ui-f25044a38e22 :size="19" /><span data-v-ui-f25044a38e22>Оплаченные заказы</span><strong data-v-ui-f25044a38e22>{{ data.sales.orders ?? '—' }}</strong><small data-v-ui-f25044a38e22>По статусу онлайн-платежа</small></article><article class="crm-surface" data-v-ui-f25044a38e22><span data-v-ui-f25044a38e22>Средний чек</span><strong data-v-ui-f25044a38e22>{{ money(data.sales.averageOrder) }}</strong><small data-v-ui-f25044a38e22>По доступным каналам</small></article></section><article data-v-ui-f25044a38e22 class="panel wide crm-surface"><div data-v-ui-f25044a38e22 class="panel-head"><div data-v-ui-f25044a38e22><p data-v-ui-f25044a38e22 class="eyebrow">СРАВНЕНИЕ КАНАЛОВ</p><h2 data-v-ui-f25044a38e22>Продажи по направлениям</h2></div></div><div data-v-ui-f25044a38e22 class="sales-table"><div data-v-ui-f25044a38e22 class="sales-row head crm-table-head"><span data-v-ui-f25044a38e22>Канал</span><span data-v-ui-f25044a38e22>Заказы</span><span data-v-ui-f25044a38e22>Сумма заказов</span><span data-v-ui-f25044a38e22>Доля</span></div><div data-v-ui-f25044a38e22 v-for="item in salesChannels" :key="item.channel" class="sales-row crm-table-row"><strong data-v-ui-f25044a38e22>{{ channelLabels[item.channel] || item.channel }}</strong><span data-v-ui-f25044a38e22>{{ item.orders }}</span><span data-v-ui-f25044a38e22>{{ money(item.revenue) }}</span><span data-v-ui-f25044a38e22>{{ data.sales.revenue ? (Number(item.revenue)/data.sales.revenue*100).toFixed(1) : 0 }}%</span></div></div></article></template>
  <template v-else><section data-v-ui-f25044a38e22 class="hero-kpis customer-kpis"><article class="crm-surface" data-v-ui-f25044a38e22><Users data-v-ui-f25044a38e22 :size="19" /><span data-v-ui-f25044a38e22>Клиентская база</span><strong data-v-ui-f25044a38e22>{{ data.customers.total ?? '—' }}</strong><small data-v-ui-f25044a38e22>B2C и B2B</small></article><article class="crm-surface" data-v-ui-f25044a38e22><ArrowUpRight data-v-ui-f25044a38e22 :size="19" /><span data-v-ui-f25044a38e22>Новые клиенты</span><strong data-v-ui-f25044a38e22>{{ data.customers.new ?? '—' }}</strong><small data-v-ui-f25044a38e22>За последние 30 дней</small></article><article class="crm-surface" data-v-ui-f25044a38e22><span data-v-ui-f25044a38e22>Открытые лиды</span><strong data-v-ui-f25044a38e22>{{ data.operations.openLeads ?? '—' }}</strong><small data-v-ui-f25044a38e22>В активной воронке</small></article><article class="crm-surface" data-v-ui-f25044a38e22><span data-v-ui-f25044a38e22>Обращения в поддержку</span><strong data-v-ui-f25044a38e22>{{ data.operations.helpdeskOpen ?? '—' }}</strong><small data-v-ui-f25044a38e22>{{ data.operations.helpdeskOverdue ?? '—' }} просрочено</small></article></section><article data-v-ui-f25044a38e22 class="panel wide narrative crm-surface"><p data-v-ui-f25044a38e22 class="eyebrow">CUSTOMER 360</p><h2 data-v-ui-f25044a38e22>Единая картина клиента</h2><p data-v-ui-f25044a38e22>Показатели этого раздела будут дополняться повторными покупками, LTV, сегментами, активностью B2B-организаций и качеством поддержки. Все метрики считаются на общих идентификаторах клиентов и заказов.</p></article></template>
</div></main></template>

<script lang="ts">
import { Headphones as HeadphonesIcon } from '@lucide/vue';
export default { components: { HeadphonesIcon } };
</script>
